#!/usr/bin/env python3
"""Builds THIRD-PARTY-LICENSES.md from the pip and npm license scans and enforces the license policy.

Usage: third-party-licenses.py <pip-licenses.json> <npm-licenses.json> <output.md>

  pip-licenses.json   written by pip-licenses (--format=json --with-urls) for analytics-service
  npm-licenses.json   written by license-checker (--production --json) for analytics-ui

Exits 1 if a component has no acceptable license, so a release cannot ship one unnoticed.
A component passes if at least one of its license alternatives is acceptable. Alternatives are
separated by OR (npm) or by ";" and " / " (pip-licenses joins multiple classifiers with ";").
"""
import json
import re
import sys

# Strong or network copyleft: never acceptable, not even with a classpath exception.
ALWAYS_DENIED = re.compile(r"AGPL|Affero|SSPL|Commons Clause|BUSL|Business Source", re.I)
# GPL/LGPL are acceptable only as an extra option or with the Classpath Exception.
COPYLEFT = re.compile(r"(^|[^A-Za-z])L?GPL|General Public License", re.I)
CLASSPATH_EXCEPTION = re.compile(r"classpath exception|CPE", re.I)
UNKNOWN = re.compile(r"^(NOT DECLARED|UNLICENSED|UNKNOWN|None|)$", re.I)

# Components whose license metadata is missing or unusable but whose license has been confirmed
# manually. Key: "pip:<name>" or "npm:<name>". Add an entry only after verifying the license at
# the source, and say how.
CONFIRMED = {
}


def acceptable(alternative: str) -> bool:
    parts = [p.strip(" ()") for p in re.split(r"\s+AND\s+", alternative)]  # AND: all must pass
    for p in parts:
        if UNKNOWN.match(p) or ALWAYS_DENIED.search(p):
            return False
        if COPYLEFT.search(p) and not CLASSPATH_EXCEPTION.search(p):
            return False
    return True


def passes(expression: str) -> bool:
    alternatives = re.split(r"\s+OR\s+|\s+/\s+|;", expression)
    return any(acceptable(a) for a in alternatives)


def main(pip_path: str, npm_path: str, out_path: str) -> int:
    rows_pip, rows_npm, violations = {}, {}, []

    for pkg in json.load(open(pip_path)):
        name, version, lic = pkg["Name"], pkg["Version"], (pkg.get("License") or "").strip()
        if UNKNOWN.match(lic):
            lic = CONFIRMED.get(f"pip:{name.lower()}", "NOT DECLARED")
        rows_pip[(name, version)] = lic.replace("\n", " ")

    for key, info in json.load(open(npm_path)).items():
        name, version = key.rsplit("@", 1)
        if name == "analytics-extension":  # this project, not a third party
            continue
        lic = info.get("licenses")
        lic = " OR ".join(lic) if isinstance(lic, list) else str(lic)
        if UNKNOWN.match(lic):
            lic = CONFIRMED.get(f"npm:{name}", lic)
        rows_npm[(name, version)] = lic

    for (n, v), lic in rows_pip.items():
        if not passes(lic):
            violations.append(f"{n}=={v} -> {lic}")
    for (n, v), lic in rows_npm.items():
        if not passes(lic):
            violations.append(f"{n}@{v} -> {lic}")

    out = [
        "# Third-party licenses", "",
        "This file lists the third-party components that the Analytics Management extension "
        "redistributes or depends on at runtime, with the license each one declares. It is "
        "generated by `.github/scripts/generate-third-party-licenses.sh` (`pip-licenses` for the "
        "backend, `license-checker` for the UI, production dependencies only) and regenerated on "
        "every release. Do not edit it by hand.", "",
        "The extension itself is licensed under the Apache License 2.0 (see [LICENSE](LICENSE)).", "",
        "## Backend (Python, analytics-service)", "",
        "| Component | Version | License |", "|---|---|---|",
    ]
    out += [f"| {n} | {v} | {lic.replace('|', '/')} |" for (n, v), lic in sorted(rows_pip.items(), key=lambda x: x[0][0].lower())]
    out += ["", "## Frontend (npm, analytics-ui)", "", "| Component | Version | License |", "|---|---|---|"]
    out += [f"| {n} | {v} | {lic.replace('|', '/')} |" for (n, v), lic in sorted(rows_npm.items())]
    open(out_path, "w").write("\n".join(out) + "\n")

    print(f"{len(rows_pip)} backend and {len(rows_npm)} frontend components written to {out_path}")
    if violations:
        print("::error::Components without an acceptable license:", file=sys.stderr)
        for v in violations:
            print(f"  {v}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    if len(sys.argv) != 4:
        sys.exit(__doc__)
    sys.exit(main(*sys.argv[1:]))
